package org.sonatype.nexus.repository.openformats;
import java.io.*;
import java.util.zip.*;
import org.apache.commons.compress.archivers.tar.*;
import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.junit.Test;
import org.sonatype.nexus.repository.view.payloads.BytesPayload;
import static org.junit.Assert.*;
public class ProtocolValidationTest {
 @Test public void sparseIndexPathsFollowCargoSpecification(){assertEquals("/1/a",CargoProtocol.indexPath("a"));assertEquals("/2/ab",CargoProtocol.indexPath("ab"));assertEquals("/3/a/abc",CargoProtocol.indexPath("abc"));assertEquals("/ab/cd/abcde",CargoProtocol.indexPath("ABCDE"));}
 @Test public void cargoRejectsArbitraryRawPaths(){assertTrue(CargoProtocol.valid("/ne/xu/nexus_fixture"));assertFalse(CargoProtocol.valid("/wrong/nexus_fixture"));assertFalse(CargoProtocol.valid("/etc/passwd"));assertFalse(CargoProtocol.valid("/api/v1/crates/new/extra"));}
 @Test public void metadataLimitIsEnforced()throws Exception {assertArrayEquals(new byte[8],ProtocolSupport.read(new BytesPayload(new byte[8],null),8));assertThrows(IllegalArgumentException.class,()->ProtocolSupport.read(new BytesPayload(new byte[9],null),8));}
 @Test public void absentBodyIsRejected(){assertThrows(IllegalArgumentException.class,()->ProtocolSupport.read(null,8));}
 @Test public void gitLfsOnlyAcceptsSha256ObjectIds(){assertTrue(GitLfsProtocol.valid("/objects/"+"a".repeat(64)));assertFalse(GitLfsProtocol.valid("/objects/../../metadata"));assertFalse(GitLfsProtocol.valid("/objects/"+"g".repeat(64)));assertFalse(GitLfsProtocol.valid("/objects/"+"a".repeat(63)));}
 @Test public void swiftRejectsUnversionedReleaseArchives(){assertTrue(SwiftProtocol.valid("/fixture/hello/1.0.0.zip"));assertFalse(SwiftProtocol.valid("/fixture/hello/main.zip"));assertFalse(SwiftProtocol.valid("/fixture/hello/1.0.0/anything"));}
 @Test public void terraformRoutesAreProtocolSpecific(){assertTrue(TerraformProtocol.valid("/v1/providers/fixture/hello/1.0.0/download/linux/amd64"));assertTrue(TerraformProtocol.valid("/v1/modules/fixture/hello/local/versions"));assertFalse(TerraformProtocol.valid("/raw/file"));assertFalse(TerraformProtocol.valid("/v1/providers/fixture/hello/not-a-version/download/linux/amd64"));}
 @Test public void swiftArchiveTraversalIsRejected()throws Exception {assertThrows(IllegalArgumentException.class,()->SwiftProtocol.manifests(zip("../Package.swift","bad")));}
 @Test public void swiftAbsoluteArchivePathIsRejected()throws Exception {assertThrows(IllegalArgumentException.class,()->SwiftProtocol.manifests(zip("/Package.swift","bad")));}
 @Test public void swiftManifestIsRecoveredFromPackageRoot()throws Exception {assertArrayEquals("manifest".getBytes(),SwiftProtocol.manifests(zip("hello/Package.swift","manifest")).get("Package.swift"));}
 @Test public void cargoArchiveWithWrongRootIsRejected()throws Exception {assertThrows(IllegalArgumentException.class,()->CargoProtocol.validateArchive(tar("wrong-1.0.0/Cargo.toml",false),"hello","1.0.0"));}
 @Test public void cargoArchiveTraversalIsRejected()throws Exception {assertThrows(IllegalArgumentException.class,()->CargoProtocol.validateArchive(tar("hello-1.0.0/../Cargo.toml",false),"hello","1.0.0"));}
 @Test public void cargoSymlinkArchiveIsRejected()throws Exception {assertThrows(IllegalArgumentException.class,()->CargoProtocol.validateArchive(tar("hello-1.0.0/Cargo.toml",true),"hello","1.0.0"));}
 @Test public void cargoManifestIsRequired()throws Exception {assertThrows(IllegalArgumentException.class,()->CargoProtocol.validateArchive(tar("hello-1.0.0/readme",false),"hello","1.0.0"));}
 @Test public void cargoValidSourceArchiveIsAccepted()throws Exception {CargoProtocol.validateArchive(tar("hello-1.0.0/Cargo.toml",false),"hello","1.0.0");}
 @Test public void checksumsCoverExactArtifactBytes(){assertEquals("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",ProtocolSupport.sha256(new byte[0]));assertNotEquals(ProtocolSupport.sha256("a".getBytes()),ProtocolSupport.sha256("a\n".getBytes()));}
 @Test public void composerPlaceholdersRemainLiteral(){assertEquals("https://registry.example/p2/%package%.json",ProtocolSupport.resolveTemplate(java.net.URI.create("https://registry.example/"),"p2/%package%.json"));}
 @Test public void encodedArtifactUrlIsPreserved(){assertEquals("https://registry.example/artifact%20name.zip",ProtocolSupport.resolveTemplate(java.net.URI.create("https://registry.example/"),"artifact%20name.zip"));}
 @Test public void composerAbsoluteTemplatePreservesItsOrigin(){assertEquals("https://cdn.example/p/%package%$%hash%.json",ProtocolSupport.resolveTemplate(java.net.URI.create("https://registry.example/"),"https://cdn.example/p/%package%$%hash%.json"));}
 @Test public void cachedMetadataUsesTheCurrentRepositoryOrigin()throws Exception {var node=ProtocolSupport.JSON.readTree("{\"dist\":{\"url\":\"http://localhost:8081/repository/example/_remote/abc\"},\"homepage\":\"https://upstream.example/page\"}");ProtocolSupport.rebase(node,"http://localhost:8081/repository/example","https://nexus.example/repository/example");assertEquals("https://nexus.example/repository/example/_remote/abc",node.path("dist").path("url").asText());assertEquals("https://upstream.example/page",node.path("homepage").asText());}
 @Test public void swiftContentVersionIsUnambiguous(){var response=new org.sonatype.nexus.repository.view.Response.Builder().status(org.sonatype.nexus.repository.view.Status.success(200)).header("Content-Version","1").header("Content-Version","1").build();assertEquals(java.util.List.of("1"),SwiftProtocol.result(response).getHeaders().getAll("Content-Version"));}
 @Test public void hubPaginationUsesRepositoryEndpoint(){assertEquals("<https://nexus.example/repository/hub/api/models/example/tree/main?cursor=opaque%2Bvalue>; rel=\"next\"",ProtocolSupport.repositoryLinks("<https://hub.example:443/prefix/api/models/example/tree/main?cursor=opaque%2Bvalue>; rel=\"next\"",java.net.URI.create("https://hub.example/prefix/"),"https://nexus.example/repository/hub"));}
 @Test public void hubPaginationCannotForwardNexusCredentialsElsewhere(){assertThrows(IllegalArgumentException.class,()->ProtocolSupport.repositoryLinks("<https://foreign.example/api/models/example/tree/main>; rel=\"next\"",java.net.URI.create("https://hub.example/"),"https://nexus.example/repository/hub"));assertThrows(IllegalArgumentException.class,()->ProtocolSupport.repositoryLinks("<https://hub.example/other/api>; rel=\"next\"",java.net.URI.create("https://hub.example/prefix/"),"https://nexus.example/repository/hub"));}
 private byte[] zip(String path,String content)throws IOException {var out=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry(path));zip.write(content.getBytes());zip.closeEntry();}return out.toByteArray();}
 private byte[] tar(String path,boolean symlink)throws IOException {var out=new ByteArrayOutputStream();try(var gzip=new GzipCompressorOutputStream(out);var tar=new TarArchiveOutputStream(gzip)){var entry=new TarArchiveEntry(path,symlink?TarConstants.LF_SYMLINK:TarConstants.LF_NORMAL);if(symlink)entry.setLinkName("/etc/passwd");else entry.setSize(1);tar.putArchiveEntry(entry);if(!symlink)tar.write('x');tar.closeArchiveEntry();}return out.toByteArray();}
}
